#include <vector>

class Solution {
public:
    int findPattern(InfiniteStream* stream, std::vector<int>& pattern) {
        int m = pattern.size();
        std::vector<int> pi(m, 0);
        int j = 0;
        for (int i = 1; i < m; ++i) {
            while (j > 0 && pattern[i] != pattern[j]) j = pi[j - 1];
            if (pattern[i] == pattern[j]) j++;
            pi[i] = j;
        }
        int idx = 0;
        j = 0;
        while (true) {
            int bit = stream->next();
            while (j > 0 && bit != pattern[j]) j = pi[j - 1];
            if (bit == pattern[j]) j++;
            if (j == m) return idx - m + 1;
            idx++;
        }
    }
};

